export {
  animatedItemsClasses,
  backdropClasses,
  defaultAnchor,
  defaultItemsClasses,
  itemClasses,
  rootClasses,
  selectedIconClasses,
  triggerClasses,
} from "./view";

export const rootClasses = "relative inline-block";

export const triggerClasses =
  "inline-flex min-w-56 cursor-pointer select-none items-center justify-between gap-3 rounded-lg border border-gray-300 bg-white px-4 py-2 text-base font-normal text-gray-900 transition hover:bg-gray-100";

export const defaultItemsClasses =
  "absolute z-10 mt-1 max-h-64 w-64 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg outline-none";

export const animatedItemsClasses =
  "absolute z-10 mt-1 max-h-64 w-64 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg outline-none transition duration-150 ease-out data-[closed]:scale-95 data-[closed]:opacity-0";

export const itemClasses =
  "group flex cursor-pointer items-center gap-2 px-3 py-2 text-base text-gray-700 data-[active]:bg-gray-100 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const selectedIconClasses =
  "h-4 w-4 shrink-0 text-gray-900 opacity-0 group-data-[selected]:opacity-100";

export const backdropClasses = "fixed inset-0 z-0";

export const defaultAnchor = {
  placement: "bottom-start" as const,
  gap: 4,
  padding: 8,
};

import { Option } from "effect";
import { describe, expect, test } from "vitest";

import * as Listbox from "./index";

type Person = "Michael Bluth" | "Lindsay Funke" | "Gob Bluth";

const PersonListbox = Listbox.create<Person>();
const listboxId = "people-listbox";

const initModel = (): Listbox.Model => Listbox.init({ id: listboxId })[0];

const FocusPeopleItems = Listbox.FocusItems({ id: listboxId });
const FocusPeopleButton = Listbox.FocusButton({ id: listboxId });

const expectSelectedOutMessage = (
  maybeOutMessage: Option.Option<Listbox.OutMessage<Person>>,
  value: Person
) => {
  expect(Option.isSome(maybeOutMessage)).toBe(true);

  if (Option.isSome(maybeOutMessage)) {
    expect(maybeOutMessage.value).toEqual(
      Listbox.Selected({ value, wasAdded: true })
    );
  }
};

describe("Listbox registry component", () => {
  describe(Listbox.init, () => {
    test("returns a model with no startup commands", () => {
      const [model, commands] = Listbox.init({ id: listboxId });

      expect(model.id).toBe(listboxId);
      expect(model.isOpen).toBe(false);
      expect(model.isAnimated).toBe(false);
      expect(model.isModal).toBe(false);
      expect(model.orientation).toBe("Vertical");
      expect(Option.isNone(model.maybeSelectedItem)).toBe(true);
      expect(commands).toEqual([]);
    });

    test("preserves selection, animation, modal, and orientation config", () => {
      const [model, commands] = Listbox.init({
        id: listboxId,
        selectedItem: "Gob Bluth",
        isAnimated: true,
        isModal: true,
        orientation: "Horizontal",
      });

      expect(model.isAnimated).toBe(true);
      expect(model.isModal).toBe(true);
      expect(model.orientation).toBe("Horizontal");
      expect(model.maybeSelectedItem).toEqual(Option.some("Gob Bluth"));
      expect(commands).toEqual([]);
    });
  });

  describe("helper API", () => {
    test("open delegates to Opened behavior", () => {
      const [model, commands, maybeOutMessage] =
        PersonListbox.open(initModel());

      expect(model.isOpen).toBe(true);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusPeopleItems.name);
      expect(commands[0]?.args).toEqual(FocusPeopleItems.args);
      expect(Option.isNone(maybeOutMessage)).toBe(true);
    });

    test("close delegates to Closed behavior", () => {
      const [openModel] = PersonListbox.open(initModel());
      const [model, commands, maybeOutMessage] = PersonListbox.close(openModel);

      expect(model.isOpen).toBe(false);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusPeopleButton.name);
      expect(commands[0]?.args).toEqual(FocusPeopleButton.args);
      expect(Option.isNone(maybeOutMessage)).toBe(true);
    });

    test("selectItem closes, stores selection, and emits a typed Selected out-message", () => {
      const [openModel] = PersonListbox.open(initModel());
      const [model, commands, maybeOutMessage] = PersonListbox.selectItem(
        openModel,
        "Lindsay Funke"
      );

      expect(model.isOpen).toBe(false);
      expect(model.maybeSelectedItem).toEqual(Option.some("Lindsay Funke"));
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusPeopleButton.name);
      expectSelectedOutMessage(maybeOutMessage, "Lindsay Funke");
    });

    test("reflectSelectedItem mirrors external truth without commands", () => {
      const model = PersonListbox.reflectSelectedItem(
        initModel(),
        Option.some("Michael Bluth")
      );

      expect(model.maybeSelectedItem).toEqual(Option.some("Michael Bluth"));
    });

    test("modal open and close include scroll and inert commands", () => {
      const [closedModel] = Listbox.init({
        id: listboxId,
        isModal: true,
      });
      const [openModel, openCommands] = PersonListbox.open(closedModel);
      const [, closeCommands] = PersonListbox.close(openModel);

      expect(openCommands.map((command) => command.name)).toEqual([
        Listbox.LockScroll().name,
        Listbox.InertOthers({ id: listboxId }).name,
        Listbox.FocusItems({ id: listboxId }).name,
      ]);
      expect(closeCommands.map((command) => command.name)).toEqual([
        Listbox.FocusButton({ id: listboxId }).name,
        Listbox.UnlockScroll().name,
        Listbox.RestoreInert({ id: listboxId }).name,
      ]);
    });
  });
});

import { Scene, Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { childAttributes, html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Listbox from "./index";

type Person = "Michael Bluth" | "Lindsay Funke" | "Gob Bluth";

const PersonListbox = Listbox.create<Person>();
const listboxId = "people-listbox";
const people: readonly Person[] = [
  "Michael Bluth",
  "Lindsay Funke",
  "Gob Bluth",
];
const anchor = Listbox.defaultAnchor;

const [initialModel] = Listbox.init({ id: listboxId });
const [animatedModel] = Listbox.init({ id: listboxId, isAnimated: true });

const AnchorPeopleListbox = Listbox.AnchorListbox({
  buttonId: `${listboxId}-button`,
  anchor,
});
const SettleItemsAnimation = Ui.Animation.WaitForAnimationSettled({
  id: `${listboxId}-listbox`,
});

const toAnimationMessage = (message: Ui.Animation.Message) =>
  Listbox.GotAnimationMessage({ message });

const resolveListboxMounts = () =>
  Scene.Mount.resolveAll(
    [Listbox.PortalListboxBackdrop, Listbox.CompletedPortalListboxBackdrop()],
    [AnchorPeopleListbox, Listbox.CompletedAnchorListbox()]
  );

const view = (model: Listbox.Model): Html => {
  const h = html<Listbox.Message>();

  return h.submodel({
    slotId: model.id,
    model,
    view: PersonListbox.view,
    viewInputs: {
      anchor,
      items: people,
      itemToConfig: (item) => ({
        classes: Listbox.itemClasses,
        content: h.span([], [item]),
      }),
      buttonContent: h.span([], ["Choose person"]),
      buttonAttributes: childAttributes([h.Class(Listbox.triggerClasses)]),
      itemsAttributes: childAttributes([
        h.Class(Listbox.defaultItemsClasses),
      ]),
      backdropAttributes: childAttributes([
        h.DataAttribute("testid", "listbox-backdrop"),
        h.Class(Listbox.backdropClasses),
      ]),
      attributes: childAttributes([h.Class(Listbox.rootClasses)]),
    },
    toParentMessage: (message) => message,
  });
};

const animatedView = (model: Listbox.Model): Html => {
  const h = html<Listbox.Message>();

  return h.submodel({
    slotId: model.id,
    model,
    view: PersonListbox.view,
    viewInputs: {
      anchor,
      items: people,
      itemToConfig: (item) => ({
        classes: Listbox.itemClasses,
        content: h.span([], [item]),
      }),
      buttonContent: h.span([], ["Choose animated person"]),
      buttonAttributes: childAttributes([h.Class(Listbox.triggerClasses)]),
      itemsAttributes: childAttributes([
        h.Class(Listbox.animatedItemsClasses),
      ]),
      backdropAttributes: childAttributes([
        h.DataAttribute("testid", "listbox-backdrop"),
        h.Class(Listbox.backdropClasses),
      ]),
      attributes: childAttributes([h.Class(Listbox.rootClasses)]),
    },
    toParentMessage: (message) => message,
  });
};

describe("Listbox registry view", () => {
  test("opens listbox items from the trigger", () => {
    Scene.scene(
      { update: PersonListbox.update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Choose person" })).toExist(),
      Scene.expect(Scene.text("Michael Bluth")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Choose person" })),
      Scene.Command.expectHas(Listbox.FocusItems({ id: listboxId })),
      Scene.Command.resolve(
        Listbox.FocusItems({ id: listboxId }),
        Listbox.CompletedFocusItems()
      ),
      resolveListboxMounts(),
      Scene.expect(Scene.text("Michael Bluth")).toExist(),
      Scene.expect(Scene.text("Lindsay Funke")).toExist(),
      Scene.expect(Scene.text("Gob Bluth")).toExist()
    );
  });

  test("closes through the backdrop", () => {
    Scene.scene(
      { update: PersonListbox.update, view },
      Scene.with(initialModel),
      Scene.click(Scene.role("button", { name: "Choose person" })),
      Scene.Command.resolve(
        Listbox.FocusItems({ id: listboxId }),
        Listbox.CompletedFocusItems()
      ),
      resolveListboxMounts(),
      Scene.click(Scene.testId("listbox-backdrop")),
      Scene.Command.expectHas(Listbox.FocusButton({ id: listboxId })),
      Scene.Command.resolve(
        Listbox.FocusButton({ id: listboxId }),
        Listbox.CompletedFocusButton()
      ),
      Scene.Mount.expectEnded(
        Listbox.PortalListboxBackdrop,
        AnchorPeopleListbox
      ),
      Scene.expect(Scene.text("Michael Bluth")).not.toExist()
    );
  });

  test("animated listbox keeps items visible after animation settles", () => {
    Scene.scene(
      { update: PersonListbox.update, view: animatedView },
      Scene.with(animatedModel),
      Scene.click(Scene.role("button", { name: "Choose animated person" })),
      Scene.Command.expectHas(
        Listbox.FocusItems({ id: listboxId }),
        Ui.Animation.RequestFrame
      ),
      Scene.Command.resolve(
        Listbox.FocusItems({ id: listboxId }),
        Listbox.CompletedFocusItems()
      ),
      Scene.Command.resolve(
        Ui.Animation.RequestFrame,
        Ui.Animation.AdvancedAnimationFrame(),
        toAnimationMessage
      ),
      resolveListboxMounts(),
      Scene.Command.resolve(
        SettleItemsAnimation,
        Ui.Animation.EndedAnimation(),
        toAnimationMessage
      ),
      Scene.expect(Scene.text("Michael Bluth")).toExist()
    );
  });
});
